	jobs := make(chan int)
	results := make(chan result)
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				if nums[i] < 0 {
					results <- result{id: i, err: errors.New("negative input")}
					continue
				}
				results <- result{id: i, val: nums[i] * nums[i]}
			}
		}()
	}
	go func() {
		defer close(jobs)
		for i := range nums {
			select {
			case jobs <- i:
			case <-ctx.Done():
				return
			}
		}
	}()
	go func() { wg.Wait(); close(results) }()

