package main

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"sync"
)

type result struct {
	id  int
	val int
	err error
}

// squareAll squares each number using `workers` goroutines. It stops early when ctx is cancelled.
func squareAll(ctx context.Context, nums []int, workers int) ([]int, error) {
	jobs := make(chan int)
	results := make(chan result)
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				if nums[i] < 0 {
					results <- result{id: i, err: errors.New("negative input")}
					continue
				}
				results <- result{id: i, val: nums[i] * nums[i]}
			}
		}()
	}
	go func() {
		defer close(jobs)
		for i := range nums {
			select {
			case jobs <- i:
			case <-ctx.Done():
				return
			}
		}
	}()
	go func() { wg.Wait(); close(results) }()

	out := make([]int, len(nums))
	var errs []error
	for r := range results {
		if r.err != nil {
			errs = append(errs, fmt.Errorf("item %d: %w", r.id, r.err))
			continue
		}
		out[r.id] = r.val
	}
	if len(errs) > 0 {
		sort.Slice(errs, func(i, j int) bool { return errs[i].Error() < errs[j].Error() })
		return out, errors.Join(errs...)
	}
	return out, ctx.Err()
}

func main() {
	out, err := squareAll(context.Background(), []int{1, 2, 3, 4, 5}, 3)
	fmt.Println(out, err)
	out, err = squareAll(context.Background(), []int{2, -3, 4, -1}, 2)
	fmt.Println(out, err)
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	_, err = squareAll(ctx, []int{1, 2, 3}, 2)
	fmt.Println(err)
}

